document.addEventListener("DOMContentLoaded",()=>{const b=document.querySelector(".mobile-toggle"),n=document.querySelector(".mobile-nav");b?.addEventListener("click",()=>{const x=b.getAttribute("aria-expanded")==="true";b.setAttribute("aria-expanded",String(!x));n.hidden=x});n?.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{n.hidden=true;b?.setAttribute("aria-expanded","false")}))});